class LRUCache:
    """Implementation of LRU Cache using a hashmap for O(1) access and a customized circular buffer to maintain order."""

    class Node:
        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.next = None

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.head = self.Node(0, 0)  # Dummy head
        self.tail = self.Node(0, 0)  # Dummy tail
        self.head.next = self.tail
        self.tail.next = self.head
        self.size = 0

    def _remove(self, node: Node):
        node.next = None  # Remove linkage from the node
        if node.key in self.cache:
            del self.cache[node.key]  # Remove from cache

    def _add_to_head(self, node: Node):
        node.next = self.head.next
        self.head.next = node
        self.cache[node.key] = node

    def get(self, key: int) -> int:
        if key in self.cache:
            node = self.cache[key]
            self._remove(node)
            self._add_to_head(node)
            return node.value
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self._remove(self.cache[key])
        new_node = self.Node(key, value)
        self._add_to_head(new_node)

        if self.size < self.capacity:
            self.size += 1
        else:
            lru_node = self.tail.next  # Get LRU node, which is right after the tail
            self._remove(lru_node)

        self._add_to_head(new_node)

class LRUCache:
    """Implementation of LRU Cache using a hashmap for O(1) access and a fixed-size list to track order of usage."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.keys = []

    def get(self, key: int) -> int:
        if key in self.cache:
            self.keys.remove(key)  # Remove the key from its current position
            self.keys.append(key)   # Add it to the end (most recently used)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key] = value
            self.keys.remove(key)  # Update its position
            self.keys.append(key)   # Move to the end
        else:
            if len(self.cache) >= self.capacity:
                lru_key = self.keys.pop(0)  # Remove the least recently used key
                del self.cache[lru_key]
            self.cache[key] = value
            self.keys.append(key)  # Add new key to the end
